impl SseEncode for crate::api::types::CrawlEvent {
    // Codec=Sse (Serialization based), see doc to use other codecs
    fn sse_encode(self, serializer: &mut flutter_rust_bridge::for_generated::SseSerializer) {
        match self {
            crate::api::types::CrawlEvent::Started { seeded, resumed } => {
                <i32>::sse_encode(0, serializer);
                <i64>::sse_encode(seeded, serializer);
                <bool>::sse_encode(resumed, serializer);
            }
            crate::api::types::CrawlEvent::Url(field0) => {
                <i32>::sse_encode(1, serializer);
                <crate::api::types::CrawledUrlEvent>::sse_encode(field0, serializer);
            }
            crate::api::types::CrawlEvent::Progress(field0) => {
                <i32>::sse_encode(2, serializer);
                <crate::api::types::ProgressSnapshot>::sse_encode(field0, serializer);
            }
            crate::api::types::CrawlEvent::Warning { message, url } => {
                <i32>::sse_encode(3, serializer);
                <String>::sse_encode(message, serializer);
                <Option<String>>::sse_encode(url, serializer);
            }
            crate::api::types::CrawlEvent::StateChanged { state } => {
                <i32>::sse_encode(4, serializer);
                <String>::sse_encode(state, serializer);
            }
            crate::api::types::CrawlEvent::AuditStarted => {
                <i32>::sse_encode(5, serializer);
            }
            crate::api::types::CrawlEvent::Audited {
                errors,
                warnings,
                notices,
                findings,
            } => {
                <i32>::sse_encode(6, serializer);
                <i64>::sse_encode(errors, serializer);
                <i64>::sse_encode(warnings, serializer);
                <i64>::sse_encode(notices, serializer);
                <i64>::sse_encode(findings, serializer);
            }
            crate::api::types::CrawlEvent::Finished { summary } => {
                <i32>::sse_encode(7, serializer);
                <crate::api::types::CrawlSummary>::sse_encode(summary, serializer);
            }
            crate::api::types::CrawlEvent::Failed { message } => {
                <i32>::sse_encode(8, serializer);
                <String>::sse_encode(message, serializer);
            }
            _ => {
                unimplemented!("");
            }
        }
    }
}

